import { Test } from 'ts-toolbelt'
import { ScriptColumn, type ScriptModule } from '../types/Script'
import type { TypeOf } from '../Column'
import { Table } from '../Table'
import { Record } from '../Record'

declare module '../types/Script' {
    export default function TestFn(_n: number, _s: string): boolean
}

import * as scriptModule from '../types/Script'

ScriptColumn({
    signature: {} as (x: number) => boolean,
    // @ts-expect-error Too few args
    default: scriptModule,
})

ScriptColumn({
    signature: {} as (x: number, y: string) => number,
    // @ts-expect-error Wrong return value
    default: scriptModule,
})

ScriptColumn({
    signature: {} as (x: number, y: number) => boolean,
    // @ts-expect-error Wrong type of args
    default: scriptModule,
})

const testA = ScriptColumn({
    // All defaults
})

const testB = ScriptColumn({
    signature: {} as (arg: { prop: number }) => string,
})

const testC = ScriptColumn({
    signature: {} as (x: number, y: string) => void, // Void is fine
    default: scriptModule,
})

type TestA = typeof testA
type TestB = typeof testB
type TestC = typeof testC

Test.checks([
    Test.check<TypeOf<TestA>, ScriptModule | string, Test.Pass>(),
    Test.check<Parameters<Exclude<TypeOf<TestB>, string>['default']>, [arg: { prop: number }], Test.Pass>(),
    Test.check<ReturnType<Exclude<TypeOf<TestB>, string>['default']>, string, Test.Pass>(),
    Test.check<Parameters<Exclude<TypeOf<TestC>, string>['default']>, [x: number, y: string], Test.Pass>(),
    Test.check<ReturnType<Exclude<TypeOf<TestC>, string>['default']>, void, Test.Pass>(),
])

const script_test_table = Table({
    name: 'script_test_table',
    schema: {
        script: testC,
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface script_test_table extends Helper<typeof script_test_table> {}
            }

            interface Tables {
                script_test_table: Table<TableSchemas.script_test_table>
            }
        }
    }
}

Record({
    $id: Now.ID['script_test_record_with_module'],
    table: 'script_test_table',
    data: {
        script: scriptModule,
    },
})

Record({
    $id: Now.ID['script_test_record_with_inline_script'],
    table: 'script_test_table',
    data: {
        script: script`gs.info('Hello, world!')`,
    },
})
